// Tests of equivalence: the two one-sided t tests (TOST) of the package equivalence's tost, and a test of equivalence
// of two proportions on counts with the score statistics of the difference.
//
// Written for rStats.js from the published methods and the package's documented behaviour (no R or package code):
// - TOST (Schuirmann, Journal of Pharmacokinetics and Biopharmaceutics 15, 1987): equivalence of the means within
//   (-epsilon, epsilon) is shown at level alpha when both H01: d <= -epsilon and H02: d >= epsilon are rejected by
//   one-sided t tests at alpha; the larger one-sided p-value is P(T > (epsilon - |d|)/se) on the df of the t test, and
//   the dual interval is d -+ qt(1 - alpha, df) se, a 1 - 2 alpha interval. The mean difference, its standard error
//   and the df are tTest's (Welch's, pooled or paired).
// - Two proportions: the same pair of one-sided hypotheses about p1 - p2, tested with the score statistic
//   z(delta0) = (p1 - p2 - delta0) / sqrt(var(delta0)) at delta0 = -epsilon and +epsilon, var at the maximum likelihood
//   estimate under p1 - p2 = delta0 (Farrington and Manning, Statistics in Medicine 9, 1990, 1447-1454), times
//   N/(N - 1) for Miettinen and Nurminen (Statistics in Medicine 4, 1985, 213-226), or at the observed proportions
//   (Wald). The statistics and the restricted MLE are those of src/htest/core/twoProportions.ts; the dual 1 - 2 alpha
//   interval is binomDiffCI's with the same method.
import { pnorm } from "../distributions/normal.js";
import { pt1, qt1 } from "../distributions/t.js";
import { reported, unreported } from "../internal/warnings.js";
import { checkTrials, levelOfAlpha } from "./binomCI.js";
import { diffDeviation, diffVariance } from "./core/twoProportions.js";
import { matchChoice } from "./power.js";
import { tTest } from "./tTest.js";
import { checkConfLevelOpen } from "./types.js";
import { binomDiffLimits } from "./twoByTwo.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const TOST_KEYS = ["epsilon", "paired", "varEqual", "confLevel", "alpha"];
const BINOM_DIFF_EQUIVALENCE_TEST_KEYS = ["margin", "method", "alpha"];
// Generated by `node scripts/option-keys.mjs --write` (end)
/** The level of a TOST: alpha in (0, 0.5), so that the 1 - 2 alpha interval is an interval */
function checkAlpha(alpha, name) {
    if (!(typeof alpha === "number" && alpha > 0 && alpha < 0.5))
        throw new RangeError(`'${name}' must be a single number in (0, 0.5)`);
}
/**
 * Two one-sided t tests (TOST) of equivalence of two means. Equivalent to `equivalence::tost()` in R.
 *
 * Equivalence, |mean(x) - mean(y)| < epsilon, is shown at level alpha = 1 - confLevel when both one-sided t tests of
 * H01: d <= -epsilon and H02: d >= epsilon reject; the p-value is the larger of their p-values and `confInt` the dual
 * 1 - 2 alpha interval (90% for the default `confLevel` 0.95). The difference, standard error and degrees of freedom are
 * those of {@link tTest} (Welch's by default, pooled with `varEqual`, paired with `paired`), with tTest's checks and
 * errors. Used on 0/1 data it compares two proportions with a t approximation; for counts
 * {@link binomDiffEquivalenceTest} is the better test.
 *
 * Unlike R, a level of 0.5 or less (`confLevel`) or of 0.5 or more (`alpha`) is an error (the interval would be empty),
 * and so is a margin that is not positive.
 *
 * @param x Sample.
 * @param y Second sample.
 * @param options See {@link TostOptions}.
 * @returns See {@link TostResult}.
 * @throws RangeError for a margin that is not positive and finite or a level out of range; Error where tTest has
 *   too few observations or the data are essentially constant.
 *
 * @example
 * ```ts
 * const r = tost([5.1, 4.9, 5.6, 5.8, 6.0, 5.4], [5.3, 5.0, 5.5, 5.7, 5.9, 5.2], { epsilon: 0.5 });
 * r.pValue;  // 0.029694342816029128
 * r.confInt; // [-0.36394177233776226, 0.4306084390044287] (a 90% interval)
 * r.result;  // "rejected"
 * ```
 *
 * @category Hypothesis tests
 */
export function tost(x, y, options = {}) {
    checkOptions(options, TOST_KEYS, "tost"); // generated: option-keys.mjs
    const epsilon = options.epsilon ?? 1;
    if (!(typeof epsilon === "number" && epsilon > 0 && epsilon < Infinity))
        throw new RangeError("'epsilon' must be a positive number");
    let confLevel;
    // the upper tail probability of the t quantile: alpha itself where given (1 - confLevel would lose its digits)
    let tail;
    if (options.alpha !== undefined) {
        // as R, alpha overrides conf.level
        checkAlpha(options.alpha, "alpha");
        confLevel = 1 - options.alpha;
        tail = options.alpha;
    }
    else {
        confLevel = options.confLevel ?? 0.95;
        checkConfLevelOpen(confLevel);
        if (!(confLevel > 0.5))
            throw new RangeError("'confLevel' must be greater than 0.5");
        tail = 1 - confLevel;
    }
    if (y === undefined)
        throw new TypeError("'y' is required");
    const paired = options.paired ?? false;
    const varEqual = options.varEqual ?? false;
    const t = unreported(() => tTest(x, y, { paired, varEqual }));
    const se = t.stdErr;
    const df = t.parameter;
    const d = typeof t.estimate === "number" ? t.estimate : t.estimate[0] - t.estimate[1];
    const pValue = pt1((epsilon - Math.abs(d)) / se, df, false, false);
    // (rule 10: for a tail below 1e-8 the upper tail itself; at alpha = 1e-12 and 8 df the quantile from 1 - alpha was
    // 69.69523624766852 for 69.69504323785972, as 1 - alpha has lost its digits)
    const q = tail < 1e-8 ? qt1(tail, df, false, false) : qt1(confLevel, df, true, false);
    const confInt = [d - q * se, d + q * se];
    return reported("tost", {
        method: t.method.replace("t-test", "TOST"),
        parameter: df,
        parameterName: "df",
        pValue,
        result: confInt[0] > -epsilon && confInt[1] < epsilon ? "rejected" : "not rejected",
        confInt,
        confLevel,
        estimate: t.estimate,
        // equivalence::tost names a paired estimate "mean of the differences" (tTest, as R's t.test, "mean difference")
        estimateNames: paired ? "mean of the differences" : t.estimateNames,
        epsilon,
        seDiff: se,
        warnings: [],
    });
}
const EQUIVALENCE_METHODS = ["mn", "mee", "wald"];
/**
 * Test of equivalence of two independent proportions x1/n1 and x2/n2 within a margin. Two one-sided tests of
 * H01: p1 - p2 <= -margin and H02: p1 - p2 >= margin, each at level `alpha`; equivalence is shown when both reject.
 * Not an R function. (The R packages in scope give the dual intervals, `DescTools::BinomDiffCI`, or test one bound at
 * a time.)
 *
 * The statistic at a bound delta0 is z = (p1 - p2 - delta0) / sqrt(var), with var the variance of p1 - p2 at the
 * maximum likelihood estimate of (p1, p2) under p1 - p2 = delta0 (Farrington and Manning 1990, `"mee"`), the same times
 * N/(N - 1) (Miettinen and Nurminen 1985, `"mn"`, the default), or at the observed proportions (`"wald"`). The
 * p-values are normal tails. The test is dual to {@link binomDiffCI} with the same method at the level 1 - 2 alpha:
 * equivalence is shown exactly when that interval, returned as `confInt`, lies inside (-margin, margin).
 *
 * The Wald variance is 0 when both proportions are 0 or 1: the statistics are then infinite and the p-values 0 or 1,
 * as binomDiffCI's Wald interval is a point there.
 *
 * @param x1 Successes in group 1.
 * @param n1 Trials in group 1.
 * @param x2 Successes in group 2.
 * @param n2 Trials in group 2.
 * @param options See {@link BinomDiffEquivalenceTestOptions}; `margin` is required.
 * @returns See {@link BinomDiffEquivalenceTestResult}.
 * @throws RangeError for counts that are not integers with 0 <= x <= n, n > 0, a margin outside (0, 1), alpha
 *   outside (0, 0.5), or an unknown method.
 *
 * @example
 * ```ts
 * const r = binomDiffEquivalenceTest(80, 100, 78, 100, { margin: 0.15 });
 * r.pValues; // [0.0018937433499954864, 0.012899725361675841]
 * r.pValue;  // 0.012899725361675841
 * r.confInt; // [-0.07557697533608577, 0.11553638647686569] (binomDiffCI, method "mn", 90%)
 * r.result;  // "rejected"
 * ```
 *
 * @category Hypothesis tests
 */
export function binomDiffEquivalenceTest(x1, n1, x2, n2, options = {}) {
    checkOptions(options, BINOM_DIFF_EQUIVALENCE_TEST_KEYS, "binomDiffEquivalenceTest"); // generated: option-keys.mjs
    const method = matchChoice(options.method, EQUIVALENCE_METHODS);
    const margin = options.margin;
    if (margin === undefined)
        throw new TypeError("'margin' is required");
    if (!(typeof margin === "number" && margin > 0 && margin < 1))
        throw new RangeError("'margin' must be a single number in (0, 1)");
    const alpha = options.alpha ?? 0.05;
    checkAlpha(alpha, "alpha");
    const [a1, m1] = checkTrials(x1, n1, "x1", "n1");
    const [a2, m2] = checkTrials(x2, n2, "x2", "n2");
    const est = a1 / m1 - a2 / m2;
    // z at delta0 = -+margin, written as diffStatistic's deviation (p1 - p2 - delta0); the variance is positive for the
    // score methods (the restricted MLE cannot put both proportions at 0 or 1 when 0 < |delta0| < 1)
    const z = (delta0) => diffDeviation(a1, m1, a2, m2, delta0) / Math.sqrt(diffVariance(a1, m1, a2, m2, delta0, method));
    const zLower = z(-margin);
    const zUpper = z(margin);
    const pValues = [pnorm(zLower, { lowerTail: false }), pnorm(zUpper)];
    const pValue = Math.max(pValues[0], pValues[1]);
    const confLevel = 1 - 2 * alpha;
    // binomDiffCI's interval at 1 - 2 alpha, from 2 alpha itself (alpha taken back as 1 - confLevel is about
    // eps / (2 alpha) relative off, and loses the level's digits for tiny alpha)
    const confInt = binomDiffLimits(a1, m1, a2, m2, method, levelOfAlpha(2 * alpha, confLevel));
    return reported("binomDiffEquivalenceTest", {
        method,
        estimate: est,
        margin,
        alpha,
        statistic: [zLower, zUpper],
        statisticName: "z",
        pValues,
        pValue,
        result: pValues[0] < alpha && pValues[1] < alpha ? "rejected" : "not rejected",
        confInt,
        confLevel,
        warnings: [],
    });
}
